4	/// The 5 colors of Magic.
5	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
6	pub enum Color {
7	    White,
8	    Blue,
9	    Black,
10	    Red,
11	    Green,
12	}
13	
14	/// What can exist in a mana pool. Includes colorless (not a color, but a mana type).
15	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
16	pub enum ManaType {
17	    White,
18	    Blue,
19	    Black,
20	    Red,
21	    Green,
22	    Colorless,
23	}
24	
25	impl From<Color> for ManaType {
26	    fn from(c: Color) -> Self {
27	        match c {
28	            Color::White => ManaType::White,
29	            Color::Blue => ManaType::Blue,
30	            Color::Black => ManaType::Black,
31	            Color::Red => ManaType::Red,
32	            Color::Green => ManaType::Green,
33	        }
34	    }
35	}
36	
37	/// A single mana symbol in a cost.
38	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
39	pub enum ManaSymbol {
40	    /// A colored mana symbol: {W}, {U}, {B}, {R}, {G}
41	    Colored(Color),
42	    /// Generic mana: {1}, {2}, etc. Can be paid with any type.
43	    Generic(u32),
44	    /// Specifically colorless mana: {C}
45	    Colorless(u32),
46	    /// Variable cost
47	    X,
48	    // Future: Hybrid(Color, Color), PhyrexianColored(Color), Snow, etc.
49	}
50	
51	/// A complete mana cost (e.g., {2}{R}{R} for a spell).
52	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
53	pub struct ManaCost {
54	    pub symbols: Vec<ManaSymbol>,
55	}
56	
57	impl ManaCost {
58	    pub fn new(symbols: Vec<ManaSymbol>) -> Self {
59	        Self { symbols }
60	    }
61	
62	    pub fn free() -> Self {
63	        Self { symbols: vec![] }
64	    }
65	
66	    /// Converted mana cost (now called "mana value").
67	    pub fn mana_value(&self) -> u32 {
68	        self.symbols.iter().map(|s| match s {
69	            ManaSymbol::Colored(_) => 1,
70	            ManaSymbol::Generic(n) => *n,
71	            ManaSymbol::Colorless(n) => *n,
72	            ManaSymbol::X => 0,
73	        }).sum()
74	    }
75	
76	    /// How much colored mana of each color is required.
77	    pub fn colored_requirements(&self) -> HashMap<Color, u32> {
78	        let mut reqs = HashMap::new();
79	        for sym in &self.symbols {
80	            if let ManaSymbol::Colored(c) = sym {
81	                *reqs.entry(*c).or_insert(0) += 1;
82	            }
83	        }
84	        reqs
85	    }
86	
87	    /// Total generic mana required.
88	    pub fn generic_amount(&self) -> u32 {
89	        self.symbols.iter().map(|s| match s {
90	            ManaSymbol::Generic(n) => *n,
91	            _ => 0,
92	        }).sum()
93	    }
94	
95	    /// Total colorless mana specifically required.
96	    pub fn colorless_amount(&self) -> u32 {
97	        self.symbols.iter().map(|s| match s {
98	            ManaSymbol::Colorless(n) => *n,
99	            _ => 0,
100	        }).sum()
101	    }
102	}
103	
104	impl std::fmt::Display for ManaCost {
105	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
106	        for sym in &self.symbols {
107	            match sym {
108	                ManaSymbol::Generic(n) => write!(f, "{{{}}}", n)?,
109	                ManaSymbol::Colored(c) => write!(f, "{{{}}}", match c {
110	                    Color::White => "W",
111	                    Color::Blue => "U",
112	                    Color::Black => "B",
113	                    Color::Red => "R",
114	                    Color::Green => "G",
115	                })?,
116	                ManaSymbol::Colorless(n) => {
117	                    for _ in 0..*n {
118	                        write!(f, "{{C}}")?;
119	                    }
120	                }
121	                ManaSymbol::X => write!(f, "{{X}}")?,
122	            }
123	        }
124	        Ok(())
125	    }
126	}
127	
128	/// Floating mana a player has available.
129	#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
130	pub struct ManaPool {
131	    pub mana: HashMap<ManaType, u32>,
132	}
133	
134	impl ManaPool {
135	    pub fn new() -> Self {
136	        Self { mana: HashMap::new() }
137	    }
138	
139	    pub fn add(&mut self, mana_type: ManaType, amount: u32) {
140	        *self.mana.entry(mana_type).or_insert(0) += amount;
141	    }
142	
143	    pub fn get(&self, mana_type: ManaType) -> u32 {
144	        *self.mana.get(&mana_type).unwrap_or(&0)
145	    }
146	
147	    pub fn total(&self) -> u32 {
148	        self.mana.values().sum()
149	    }
150	
151	    pub fn empty(&mut self) {
152	        self.mana.clear();
153	    }
154	
155	    pub fn is_empty(&self) -> bool {
156	        self.total() == 0
157	    }
158	}
159	
160	impl Default for ManaPool {
161	    fn default() -> Self {
162	        Self::new()
163	    }
164	}
